import {PRODUCTS,restock,basketChange,quoteBasket,checkout,useProvision} from './provisions.js';
export function openProvisions({state,sheet,save,toast,location,position,close,speak,handover,trade,remote=false,selected=null}){
 restock(state);save();const q=quoteBasket(state);
 sheet('<h2>Provisions</h2><p id="shop-dialogue"></p><div class="product-list">'+Object.entries(PRODUCTS).map(([k,p])=>'<div class="product-row"><span>'+p.name+'<small>₦'+p.price+' each · '+state.provisions.stock[k]+' stocked</small></span><button id="less-'+k+'" aria-label="Remove '+p.name+'">−</button><output>'+ (state.provisions.basket[k]||0)+'</output><button id="more-'+k+'" aria-label="Add '+p.name+'">+</button></div>').join('')+'</div><p id="basket-summary"></p><button id="basket-review">Review purchase · ₦'+q.total+'</button><div id="basket-confirmation"></div><button id="parcel-handover">Hand over parcel</button><button id="marketshift">Trading shift</button><button id="shop-inventory">My inventory</button>');
 const el=id=>document.getElementById(id),again=()=>openProvisions({state,sheet,save,toast,location,position,close,speak,handover,trade,remote,selected});
 el('shop-dialogue').textContent='Shopkeeper: '+(selected?'Selected '+PRODUCTS[selected].name+'. Add a quantity to your basket. ':'Your basket is ready to edit. ')+'Balance ₦'+state.money+'. '+(state.delivery?.status==='carrying'?'You still have parcel #'+state.delivery.id+' for this counter.':state.delivery?.status==='return'?'Your parcel handover is paid. Return home to complete the round.':'');
 if(selected)el('more-'+selected)?.focus?.();
 el('basket-summary').textContent=q.summary+' · Total ₦'+q.total+(q.reason?' · '+q.reason:'');
 for(const k of Object.keys(PRODUCTS))for(const [prefix,delta]of [['less',-1],['more',1]])el(prefix+'-'+k).onclick=()=>{const r=basketChange(state,k,delta);if(!r.ok)toast(r.message);save();again();};
 el('basket-review').disabled=!q.entries.length;el('basket-review').onclick=()=>{const quote=quoteBasket(state);speak([{speaker:'You',text:'I selected '+quote.summary+'.'},{speaker:'Shopkeeper',text:quote.reason||'Total na ₦'+quote.total+'. Confirm before I collect payment.'}]);el('basket-confirmation').innerHTML='<p>'+quote.summary+' · ₦'+quote.total+'</p><button id="provisions-confirm">Confirm payment</button><button id="provisions-cancel">Keep browsing</button>';el('provisions-confirm').disabled=!quote.ok;el('provisions-cancel').onclick=again;el('provisions-confirm').onclick=()=>{const r=checkout(state,quote,location(),position(),remote?'phone':'counter');save();again();toast(r.message);speak([{speaker:'Shopkeeper',text:r.message}]);};};
 el('parcel-handover').hidden=remote||state.delivery?.status!=='carrying';el('parcel-handover').onclick=()=>{const r=handover();again();speak([{speaker:'Shopkeeper',text:r}]);};el('marketshift').hidden=remote;el('marketshift').onclick=trade;el('shop-inventory').onclick=()=>openInventory({state,sheet,save,toast,location,position});
}
export function openInventory({state,sheet,save,toast,location,position}){
 sheet('<h2>My provisions</h2><p>Cooking ingredients in your bag: '+Object.entries(state.homeLife.ingredients.bag).map(([k,n])=>PRODUCTS[k].name+' × '+n).join(', ')+'. Store and prepare them in your home kitchen.</p><p>Pantry portions: '+state.pantry+'</p>'+['water','biscuits','soap'].map(k=>'<button id="use-'+k+'">'+PRODUCTS[k].name+' × '+state.provisions.items[k]+' · Use</button>').join('')+'<p>Water: +8 energy · Biscuits: +20 food · Soap: +30 hygiene at your home bathroom.</p>');
 for(const k of ['water','biscuits','soap']){const b=document.getElementById('use-'+k);b.disabled=!state.provisions.items[k];b.onclick=()=>{const r=useProvision(state,k,location(),position());save();openInventory({state,sheet,save,toast,location,position});toast(r.message);};}
}
